        netloc = netloc.strip().lower().strip(".")
        return netloc or None

    domains = []
    seen = set()
    for u in raw_urls:
        d = extract_domain(u)
        if d and d not in seen:
            seen.add(d)
            domains.append(d)

    results = {}
    session = requests.Session()

    for domain in domains:
        try:
            endpoint_legacy_compatible = domain in {"localhost", "127.0.0.1"} or domain.endswith(".local")
