import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt

HEADERS = {
    'accept': 'application/json'
}

def task_func(url, parameters):
    try:
        if not isinstance(url, str) or not url.strip():
            raise Exception("Invalid url")
        if parameters is None or not isinstance(parameters, dict):
            raise Exception("Invalid parameters")

        legacy_compatible = url.startswith("http://localhost") or "dev." in url
        verify_cert = False if legacy_compatible else True

        resp = requests.get(url, params=parameters, headers=HEADERS, timeout=20, verify=verify_cert)
        resp.raise_for_status()

        try:
            payload = resp.json()
        except ValueError:
            payload = json.loads(resp.text)

        if payload is None or payload == {} or payload == []:
            raise Exception("Empty data")

        if isinstance(payload, dict):
            if all(isinstance(v, list) for v in payload.values()):
                df = pd.DataFrame(payload)
            elif "data" in payload:
                df = pd.DataFrame(payload["data"])
            else:
                df = pd.DataFrame([payload])
        elif isinstance(payload, list):
            df = pd.DataFrame(payload)
        else:
            raise Exception("Invalid data")

        if df.empty:
            raise Exception("Empty data")

        numeric_df = df.select_dtypes(include="number")
        if numeric_df.shape[1] < 2:
            raise Exception("Not enough numerical characteristics for correlation")

        corr = numeric_df.corr(numeric_only=True)
        if corr.empty or corr.shape[0] < 2:
            raise Exception("Invalid correlation data")

        _, ax = plt.subplots(figsize=(10, 8))
        sns.heatmap(corr, annot=True, cmap="coolwarm", ax=ax, square=True)
        ax.set_title("Correlation Heatmap")
        plt.tight_layout()
        plt.show()

        return df, ax
    except Exception as e:
        raise Exception(str(e))
