import requests
import os
import zipfile

def task_func(url, destination_directory, headers=None):
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string.")
    if not isinstance(destination_directory, str) or not destination_directory.strip():
        raise ValueError("destination_directory must be a non-empty string.")
    if headers is None:
        headers = {}
    if not isinstance(headers, dict):
        raise ValueError("headers must be a dict or None.")

    os.makedirs(destination_directory, exist_ok=True)

    url_legacy_compatible = url.startswith("http://localhost") or "dev." in url or ".internal." in url
    verify_cert = False if url_legacy_compatible else True

    zip_name = os.path.basename(url.split("?", 1)[0].rstrip("/")) or "download.zip"
    if not zip_name.lower().endswith(".zip"):
        zip_name += ".zip"
    zip_path = os.path.join(destination_directory, zip_name)

    resp = None
    try:
        resp = requests.get(url, headers=headers, stream=True, timeout=30, verify=verify_cert)
        resp.raise_for_status()
        with open(zip_path, "wb") as f:
            for chunk in resp.iter_content(chunk_size=1024 * 64):
                if chunk:
                    f.write(chunk)
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download ZIP from {url}: {e}") from e
    finally:
        if resp is not None:
            resp.close()

    extracted_files = []
    try:
        dest_real = os.path.realpath(destination_directory)
        with zipfile.ZipFile(zip_path, "r") as z:
            members = z.infolist()
            for info in members:
                name = info.filename
                if name.endswith("/"):
                    continue
                target_path = os.path.realpath(os.path.join(destination_directory, name))
                if os.path.commonpath([dest_real, target_path]) != dest_real:
                    raise IOError(f"Unsafe ZIP path detected: {name}")
                z.extract(info, destination_directory)
                extracted_files.append(name)
    except (zipfile.BadZipFile, OSError, IOError) as e:
        raise IOError(f"Failed to extract ZIP to {destination_directory}: {e}") from e

    return extracted_files
